extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var switch_script := load("res://switch.gd")
	if not check("script_exists", switch_script != null, "Lo script res://switch.gd deve esistere"):
		return

	var find_child_count := count_in_code("res://switch.gd", "find_child")
	check("no_find_child", find_child_count == 0, "Lo script switch.gd non deve più usare find_child() (trovati %d usi)" % find_child_count)

	var has_process := count_in_code("res://switch.gd", "_process")
	check("no_process", has_process == 0, "Lo script switch.gd non deve più usare _process() per controllare l'input (trovati %d usi)" % has_process)

	var switch_scene := load("res://switch.tscn") as PackedScene
	if not check("scene_exists", switch_scene != null, "La scena res://switch.tscn deve caricarsi correttamente"):
		return

	var switch_node := switch_scene.instantiate() as Area2D
	get_tree().root.add_child(switch_node)
	await wait_frames(2)

	var player_body := CharacterBody2D.new()
	player_body.name = "Player"
	get_tree().root.add_child(player_body)
	await wait_frames(2)

	call_if_exists(switch_node, "_on_body_entered", [player_body])
	var is_near: bool = bool(get_prop(switch_node, "is_player_nearby", false))
	check("player_near", is_near, "Quando il nodo Player entra nell'Area2D, is_player_nearby deve diventare true")

	var was_active: bool = bool(get_prop(switch_node, "is_active", false))
	call_if_exists(switch_node, "toggle", [])
	var is_active_now: bool = bool(get_prop(switch_node, "is_active", false))
	check("toggled", is_active_now != was_active, "Chiamando toggle() l'interruttore deve cambiare stato (is_active)")

	switch_node.queue_free()
	player_body.queue_free()
	await wait_frames(2)

