func _run_tests() -> void:
	var enemy_script := load("res://enemy.gd")
	if not check("script_exists", enemy_script != null, "Lo script res://enemy.gd deve esistere"):
		return

	var code := source_of("res://enemy.gd")
	var physics_proc_idx := code.find("func _physics_process")
	if physics_proc_idx != -1:
		var end_idx := code.find("func ", physics_proc_idx + 15)
		var physics_code := code.substr(physics_proc_idx, end_idx - physics_proc_idx if end_idx != -1 else -1)
		var has_check_player := physics_code.contains("_check_for_player") or physics_code.contains("_check_lost_player")
		check("no_check_in_physics", not has_check_player, "La funzione _physics_process non deve più chiamare _check_for_player() o _check_lost_player() ad ogni fotogramma")

	var enemy_scene := load("res://enemy.tscn") as PackedScene
	if not check("scene_exists", enemy_scene != null, "La scena res://enemy.tscn deve caricarsi correttamente"):
		return

	var enemy := enemy_scene.instantiate() as CharacterBody2D
	get_tree().root.add_child(enemy)
	await wait_frames(2)

	var player_body := CharacterBody2D.new()
	player_body.name = "Player"
	player_body.position = Vector2(50.0, 0.0)
	get_tree().root.add_child(player_body)
	await wait_frames(2)

	enemy.set("player", player_body)

	call_if_exists(enemy, "_on_path_timer_timeout", [])
	var state_val = get_prop(enemy, "current_state", -1)
	check("state_chase", int(state_val) == 1, "Quando scatta il timer e il giocatore è in vista, il nemico deve passare allo stato CHASE (1)")

	player_body.position = Vector2(600.0, 0.0)
	call_if_exists(enemy, "_on_path_timer_timeout", [])
	var state_after = get_prop(enemy, "current_state", -1)
	check("state_return", int(state_after) == 2, "Quando scatta il timer e il nemico perde di vista il giocatore, deve passare allo stato RETURN (2)")

	enemy.queue_free()
	player_body.queue_free()
	await wait_frames(2)

