extends CharacterBody2D

enum State { PATROL, CHASE, RETURN }

@export var speed: float = 70.0
@export var chase_speed: float = 110.0
@export var vision_distance: float = 180.0
@export var waypoints: Array[Node2D] = []

var current_state: State = State.PATROL
var current_waypoint_index: int = 0
var player: Node2D = null

@onready var ray_cast: RayCast2D = $RayCast2D
@onready var health: Health = $Health
@onready var navigation_agent: NavigationAgent2D = $NavigationAgent2D
@onready var path_timer: Timer = $PathTimer


func _ready() -> void:
	if health != null:
		health.died.connect(_on_died)

	path_timer.timeout.connect(_on_path_timer_timeout)

	var current_scene := get_tree().current_scene
	if current_scene != null:
		var found_player := current_scene.find_child("Player", true, false)
		if found_player is Node2D:
			player = found_player as Node2D

	_setup_navigation.call_deferred()


func _setup_navigation() -> void:
	await get_tree().physics_frame
	_update_navigation_target()


func _physics_process(delta: float) -> void:
	match current_state:
		State.PATROL:
			_process_patrol()
		State.CHASE:
			_process_chase()
		State.RETURN:
			_process_return()

	move_and_slide()


func _process_patrol() -> void:
	if waypoints.is_empty():
		velocity = Vector2.ZERO
		return

	var target: Node2D = waypoints[current_waypoint_index]
	if target == null:
		return

	if global_position.distance_to(target.global_position) < 8.0:
		current_waypoint_index = (current_waypoint_index + 1) % waypoints.size()
		target = waypoints[current_waypoint_index]
		if target == null:
			return

	var direction := global_position.direction_to(target.global_position)
	velocity = direction * speed


func _process_chase() -> void:
	if player == null:
		velocity = Vector2.ZERO
		return
	if navigation_agent.is_navigation_finished():
		velocity = Vector2.ZERO
		return
	var next_position: Vector2 = navigation_agent.get_next_path_position()
	var direction := global_position.direction_to(next_position)
	velocity = direction * chase_speed


func _process_return() -> void:
	if waypoints.is_empty():
		current_state = State.PATROL
		return

	var target: Node2D = waypoints[current_waypoint_index]
	if target == null:
		return

	if navigation_agent.is_navigation_finished() or global_position.distance_to(target.global_position) < 8.0:
		current_state = State.PATROL
		velocity = Vector2.ZERO
		return

	var next_position: Vector2 = navigation_agent.get_next_path_position()
	var direction := global_position.direction_to(next_position)
	velocity = direction * speed


func _update_navigation_target() -> void:
	match current_state:
		State.CHASE:
			if player != null:
				navigation_agent.target_position = player.global_position
		State.RETURN:
			if not waypoints.is_empty() and waypoints[current_waypoint_index] != null:
				navigation_agent.target_position = waypoints[current_waypoint_index].global_position


func _on_path_timer_timeout() -> void:
	match current_state:
		State.PATROL, State.RETURN:
			_check_for_player()
		State.CHASE:
			_check_lost_player()

	if current_state == State.CHASE or current_state == State.RETURN:
		_update_navigation_target()


func _can_see_player() -> bool:
	if player == null:
		return false

	if global_position.distance_to(player.global_position) > vision_distance:
		return false

	ray_cast.target_position = ray_cast.to_local(player.global_position)
	ray_cast.force_raycast_update()

	if ray_cast.is_colliding():
		var collider := ray_cast.get_collider()
		return collider == player

	return false


func _check_for_player() -> void:
	if _can_see_player():
		current_state = State.CHASE
		_update_navigation_target()


func _check_lost_player() -> void:
	if not _can_see_player():
		current_state = State.RETURN
		_update_navigation_target()


func _on_died() -> void:
	queue_free()

